class Solution:
    def cloneGraph(self, node: 'Node') -> 'Node':
        if not node:
            return None
        cloned = {node: Node(node.val)}
        from collections import deque
        queue = deque([node])
        while queue:
            curr = queue.popleft()
            for nei in curr.neighbors:
