class Solution:
    def sortedSquares(self, nums: List[int]) -> List[int]:
        n = len(nums)
        res = [0] * n
        l, r, pos = 0, n-1, n-1
        while l <= r:
            if abs(nums[l]) >= abs(nums[r]):
                res[pos] = nums[l] ** 2
                l += 1
            else:
                res[pos] = nums[r] ** 2
                r -= 1
            pos -= 1
        return res

class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        left = zeros = result = 0
        for right in range(len(nums)):
            if nums[right] == 0:
                zeros += 1
            while zeros > k:
                if nums[left] == 0:
                    zeros -= 1
                left += 1
            result = max(result, right - left + 1)
        return result

class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        def can_ship(cap):
            d, curr = 1, 0
            for w in weights:
                if curr + w > cap:
                    d += 1
                    curr = w
                else:
                    curr += w
            return d <= days
        lo, hi = max(weights), sum(weights)
        while lo < hi:
            mid = (lo + hi) // 2
            if can_ship(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

